from __future__ import annotations

import re
import sys
from collections import Counter

HELP = (
10→    "Usage: textstats [--top N]  # read stdin, print word and line counts; "
    "with --top N also print the N most frequent words\n"
)
TOP_N = re.compile(r"[1-9][0-9]*")


def count_words(text: str) -> int:
    return len(text.split())


20→def count_lines(text: str) -> int:
    if text == "":
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def rank_words(text: str, limit: int) -> list[tuple[str, int]]:
    counts = Counter(text.split())
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]
30→

def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--help"]:
        sys.stdout.write(HELP)
        return 0
    limit: int | None = None
    if args:
        if len(args) == 2 and args[0] == "--top" and TOP_N.fullmatch(args[1]):
40→            limit = int(args[1])
        else:
            sys.stderr.write(HELP)
            return 2
    data = sys.stdin.read()
    sys.stdout.write(f"words: {count_words(data)}\nlines: {count_lines(data)}\n")
    if limit is not None:
        for word, frequency in rank_words(data, limit):
            sys.stdout.write(f"{word} {frequency}\n")
    return 0
